package cn.pi.dailyone;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.webkit.*;import android.view.*;import android.widget.*;import java.io.*;import org.json.JSONObject;
/** Activity navigation only; authentication and WebView policy live in their own components. */
public class MainActivity extends Activity {
 private WebView web;private FrameLayout frame;private TextView status;private AuthController auth;private UpdateController updates;private String dashboardScript,authScript;private boolean dashboard=true,destroyed=false,submitting=false;private String currentAccount="",currentName="";private WebMessagePort[] statePorts;private int pageEpoch;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xFFF5F7FA);getWindow().setNavigationBarColor(0xFFF5F7FA);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
 frame=new FrameLayout(this);frame.setBackgroundColor(0xFFF5F7FA);if(Build.VERSION.SDK_INT>=35)frame.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets a=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(a.left,a.top,a.right,a.bottom);return i;});LinearLayout root=new LinearLayout(this);root.setOrientation(1);frame.addView(root,new FrameLayout.LayoutParams(-1,-1));
 LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(19),dp(2),dp(15),dp(2));status=new TextView(this);status.setText("DailyOne");status.setTextColor(0xFF28384D);status.setTextSize(19);status.setTypeface(null,1);status.setGravity(Gravity.CENTER_VERTICAL);bar.addView(status,new LinearLayout.LayoutParams(0,dp(46),1));
 for(String label:new String[]{"账号","同步"}){Button t=smallButton(label);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(52),dp(32));lp.leftMargin=dp(7);bar.addView(t,lp);t.setOnClickListener(v->{if(label.equals("账号"))openAccount();else if(dashboard)web.reload();else home();});}root.addView(bar);
 web=new WebView(this);WebSupport.configure(web);web.setBackgroundColor(0xFFF5F7FA);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(frame);
 try{StringBuilder js=new StringBuilder();for(String path:new String[]{"vendor/turndown.js","vendor/gfm.js","vendor/marked.js","editor-core.js","dashboard.js"})js.append(asset(path)).append('\n');dashboardScript=js.toString();authScript=asset("auth-page.js");}catch(Exception e){status.setText("资源加载失败");return;}
 web.setWebViewClient(new WebViewClient(){
 @Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){Uri u=r.getUrl();if("dailyone".equals(u.getScheme())){if(!r.isForMainFrame()||!WebSupport.official(w))return true;String h=u.getHost();if("update".equals(h)){if(updates!=null)updates.check();}else if("home".equals(h))home();else if("store".equals(h)){dashboard=false;web.loadUrl("https://leetcode.cn/points/");}else if("problem".equals(h)){String slug=u.getQueryParameter("slug");if(slug!=null&&slug.matches("[a-zA-Z0-9-]+")){dashboard=false;web.loadUrl("https://leetcode.cn/problems/"+slug+"/");}}return true;}return WebSupport.route(MainActivity.this,u);}
 @Override public void onPageStarted(WebView w,String url,android.graphics.Bitmap icon){pageEpoch++;closeStatePorts();}
 @Override public void onPageFinished(WebView w,String url){CookieManager.getInstance().flush();if(dashboard&&WebSupport.official(w)){final int epoch=pageEpoch;w.evaluateJavascript(dashboardScript,ignored->{if(!destroyed&&epoch==pageEpoch&&WebSupport.official(w))connectState(epoch);});}}
 @Override public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())status.setText("网络异常 · 同步");}
 });updates=new UpdateController(this);home();}
 private void openAccount(){if(auth!=null&&auth.isOpen())return;if(submitting){Toast.makeText(this,"正在提交或判题，请等待结果后切换账号",Toast.LENGTH_SHORT).show();return;}if(currentAccount.isEmpty()){startLogin(false);return;}new AlertDialog.Builder(this).setTitle("账号管理").setMessage("当前账号："+currentName+"\n@"+currentAccount).setPositiveButton("切换账号",(d,w)->{if(!submitting)startLogin(true);}).setNegativeButton("取消",null).show();}
 private void connectState(final int epoch){closeStatePorts();statePorts=web.createWebMessageChannel();statePorts[0].setWebMessageCallback(new WebMessagePort.WebMessageCallback(){@Override public void onMessage(WebMessagePort port,WebMessage message){if(destroyed||epoch!=pageEpoch||!WebSupport.official(web))return;JSONObject state=WebSupport.decode(message.getData());currentAccount=state.optString("username");currentName=state.optString("name",currentAccount);submitting=state.optBoolean("busy");}});web.postWebMessage(new WebMessage("dailyone-session-state",new WebMessagePort[]{statePorts[1]}),Uri.parse("https://leetcode.cn"));}
 private void closeStatePorts(){if(statePorts!=null){for(WebMessagePort p:statePorts)try{p.close();}catch(Exception e){}statePorts=null;}}
 private void startLogin(boolean switchAccount){if(auth!=null&&auth.isOpen())return;if(switchAccount){currentAccount="";currentName="";submitting=false;closeStatePorts();web.stopLoading();web.loadUrl("about:blank");}auth=new AuthController(this,frame,authScript,signedIn->{auth=null;if(!destroyed)home();});auth.show(switchAccount);}
 private void home(){dashboard=true;status.setText("DailyOne");web.loadUrl("https://leetcode.cn/problemset/");}
 private String asset(String path)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getAssets().open(path)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}return out.toString("UTF-8");}
 private Button smallButton(String label){Button b=new Button(this);b.setText(label);b.setTextSize(11);b.setTextColor(0xFF5C6F89);b.setAllCaps(false);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(0,0,0,0);GradientDrawable bg=new GradientDrawable();bg.setColor(0xFFE9EEF5);bg.setCornerRadius(dp(10));b.setBackground(bg);return b;}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 @Override protected void onResume(){super.onResume();if(auth!=null)auth.foreground(true);}
 @Override protected void onPause(){if(auth!=null)auth.foreground(false);super.onPause();}
 @Override public void onBackPressed(){if(auth!=null&&auth.isOpen()){auth.close(true,false);return;}if(!dashboard){home();return;}web.evaluateJavascript("(function(){const h=document.getElementById('dailyone-host');if(!h)return false;h.setAttribute('data-back-handled','0');h.dispatchEvent(new Event('dailyone-back'));return h.getAttribute('data-back-handled')==='1';})()",handled->{if(!destroyed&&!"true".equals(handled))new AlertDialog.Builder(this).setMessage("退出每日一题？").setPositiveButton("退出",(d,w)->finish()).setNegativeButton("取消",null).show();});}
 @Override protected void onDestroy(){destroyed=true;if(updates!=null)updates.close();closeStatePorts();if(auth!=null)auth.close(false,false);WebSupport.destroy(web);super.onDestroy();}
}
